/* SPDX-License-Identifier: LGPL-2.1-or-later */

#include <stdlib.h>
#include <string.h>

#include "alloc-util.h"
#include "string-util.h"
#include "tests.h"
#include "utf8.h"

TEST(ellipsize_mem_ascii_with_tab_non_utf8_locale) {
        /* Documented contract: a fully ASCII string in a non-UTF-8 locale is ellipsized with "...", not
         * with a unicode ellipsis. This must not depend on whether the string contains a tab. */
        const char *input = "abcdefghijklmnopqrstuvwx\tyz";
        _cleanup_free_ char *t = NULL, *u = NULL;

        ASSERT_OK_ERRNO(setenv("SYSTEMD_UTF8", "0", /* overwrite= */ true));
        ASSERT_OK_ERRNO(setenv("LC_ALL", "C", /* overwrite= */ true));

        /* Without a tab: reference behaviour */
        ASSERT_NOT_NULL(u = ellipsize_mem("abcdefghijklmnopqrstuvwxyz", 26, 10, 50));
        log_info("no tab:   <%s>", u);
        ASSERT_TRUE(ascii_is_valid(u));

        /* With a tab */
        ASSERT_NOT_NULL(t = ellipsize_mem(input, strlen(input), 10, 50));
        log_info("with tab: <%s>", t);
        ASSERT_TRUE(ascii_is_valid(t));
}

DEFINE_TEST_MAIN(LOG_INFO);

